# all foreground interior skip rails colors 1/2 frame, 0,2 header; background 8; components only in canvas rows>=1 cols>=1, all !=8
seen=set(); comps=[]
for r in range(1,20):
 for c in range(1,8):
  if G[r,c]==8 or (r,c) in seen: continue
  stack=[(r,c)];seen.add((r,c));cells=[]
  while stack:
   x,y=stack.pop();cells.append((x,y))
   for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    a,b=p
    if 1<=a<20 and 1<=b<8 and G[a,b]!=8 and p not in seen: seen.add(p);stack.append(p)
  comps.append(cells)
for cc in sorted(comps,key=lambda cells:(min(x for x,y in cells),min(y for x,y in cells))):
 r0=min(x for x,y in cc);r1=max(x for x,y in cc);c0=min(y for x,y in cc);c1=max(y for x,y in cc)
 print((r0,r1,c0,c1), sorted(set(G[x,y] for x,y in cc)))
 print(G[r0:r1+1,c0:c1+1].tolist())

